double h = (b - a) / 2.0;
double T0 = (f->eval(a) + f->eval(b)) * h;
double T1 = T0 / 2.0 + h * f->eval((a + b) / 2.0);
double error = std::abs(T1 - T0) / 3.0;

if (error < precision) {
    return T1;
}

int max_depth = 20;
int depth = 0;
double result = 0.0;
double a1 = a, b1 = (a + b) / 2.0;
double a2 = (a + b) / 2.0, b2 = b;

while (depth < max_depth) {
    h = (b1 - a1) / 2.0;
    double T0_1 = (f->eval(a1) + f->eval(b1)) * h;
    double T1_1 = T0_1 / 2.0 + h * f->eval((a1 + b1) / 2.0);
    double error1 = std::abs(T1_1 - T0_1) / 3.0;

    h = (b2 - a2) / 2.0;
    double T0_2 = (f->eval(a2) + f->eval(b2)) * h;
    double T1_2 = T0_2 / 2.0 + h * f->eval((a2 + b2) / 2.0);
    double error2 = std::abs(T1_2 - T0_2) / 3.0;

    if (error1 + error2 < precision) {
        result = T1_1 + T1_2;
        break;
    }

    depth++;
    double mid1 = (a1 + b1) / 2.0;
    double mid2 = (a2 + b2) / 2.0;
    a1 = mid1;
    b1 = b1;
    a2 = a2;
    b2 = mid2;
}

return result;

